var i=`0728-peanut-fish-stew`;var n=`world-0728`;var s=`GQ`;var a=`central-africa`;var o=4;var r=50;var l={en:`Peanut Fish Stew`,ua:`Риба в арахісовому соусі`};var u={en:`Peanut Fish Stew is a Equatorial Guinea classic prepared with yellow onion, tomato, scotch bonnet pepper, fish (unspecified). A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Риба в арахісовому соусі, страва кухні країни Екваторіальна Гвінея зі складниками: жовта цибуля, помідор, перець скотч-боннет, риба (невизначений вид). Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var g=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 11 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 11 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:11,i:[[`yellow-onion`,180,`g`],[`tomato`,330,`g`],[`peanut-oil`,50,`ml`],[`scotch-bonnet-pepper`,1,`pcs`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 35 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 35 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:35,i:[[`fish-unspecified`,740,`g`],[`peanut-butter`,190,`g`],[`water`,680,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`garlic`,3,`clove`],[`table-salt`,null,`to_taste`]]}];var h={slug:i,id:n,country:`GQ`,region:a,servings:4,minutes:50,title:l,text:u,steps:g};export{s as country,h as default,n as id,r as minutes,a as region,o as servings,i as slug,g as steps,u as text,l as title};